// ============================================================ EVENTI
SAP.events.push(
  {t: 0.0512, title: "La più antica storia dipinta", text: "Nella grotta di Leang Karampuang, a Sulawesi (Indonesia), una pittura mostra tre figure umane che interagiscono con un maiale selvatico: ha almeno 51.200 anni (Nature, 2024). È la più antica scena «narrativa» conosciuta. Nel 2026, sulla vicina isola di Muna, uno stencil di mano è stato datato ad almeno 67.800 anni.", cat: "umani", lat: -4.95, lon: 119.6, wiki: "Leang Karampuang", wikiEn: "Leang Karampuang"},
  {t: 0.054, title: "Sapiens a Grotta Mandrin", text: "Nella Grotta Mandrin, nella valle del Rodano, un dente e strumenti molto fini indicano sapiens già 54.000 anni fa, tra due occupazioni neanderthaliane. Sarebbe la prima presenza in Europa occidentale, ma senza discendenti. L'interpretazione è discussa.", cat: "umani", lat: 44.49, lon: 4.76, wiki: "Grotta Mandrin", wikiEn: "Grotte Mandrin"},
  {t: 0.0505, t2: 0.0435, title: "L'incrocio con i Neanderthal", text: "Due grandi studi del 2024, guidati da Leonardo Iasi (Science) e Arev Sümer (Nature) con Johannes Krause, collocano l'incrocio principale con i Neanderthal tra circa 50.500 e 43.500 anni fa, durato alcune migliaia di anni. Avvenne in un'unica grande fase comune agli antenati di tutti i non africani. Per questo europei, asiatici, nativi americani e oceaniani hanno circa il 2% di DNA neanderthaliano.", cat: "umani", lat: 33.0, lon: 36.0, big: true, wiki: "Ibridazione tra Neanderthal e Homo sapiens", wikiEn: "Interbreeding between archaic and modern humans", sci: ["paabo", "krause", "reich"]},
  {t: 0.047, t2: 0.045, title: "Ranis: i primi europei del nord", text: "A Ranis, in Germania, resti di circa 47.000–45.000 anni mostrano che i sapiens vivevano in un clima freddo di steppa. I loro genomi (2024) sono imparentati con la donna di Zlatý kůň, in Cechia. Questo piccolo gruppo non ha discendenti tra gli europei di oggi.", cat: "umani", lat: 50.66, lon: 11.57, wiki: "Ranis", wikiEn: "Ilsenhöhle", sci: ["krause"]},
  {t: 0.046, title: "Bacho Kiro", text: "Nella grotta di Bacho Kiro, in Bulgaria, sapiens di 46.000–43.000 anni avevano antenati neanderthaliani vissuti solo poche generazioni prima. I loro genomi sono più vicini agli asiatici orientali di oggi che agli europei. L'Europa fu popolata da ondate successive, alcune estinte.", cat: "umani", lat: 42.95, lon: 25.43, wiki: "Grotta di Bacho Kiro", wikiEn: "Bacho Kiro cave"},
  {t: 0.045, title: "Ust'-Ishim, il genoma più antico", text: "Un femore trovato per caso sulle rive del fiume Irtyš, in Siberia, appartiene a un uomo vissuto circa 45.000 anni fa. Il suo genoma, letto nel 2014, contiene lunghi tratti di DNA neanderthaliano, che ha permesso di datare l'incrocio. Non ha discendenti diretti tra gli umani di oggi.", cat: "umani", lat: 57.7, lon: 71.2, wiki: "Uomo di Ust'-Ishim", wikiEn: "Ust'-Ishim man", sci: ["paabo"]},
  {t: 0.042, title: "Lago Mungo", text: "Sulle rive di un lago oggi asciutto, in Australia, furono sepolti circa 42.000 anni fa Mungo Lady, cremata, e Mungo Man, cosparso di ocra rossa. Sono le più antiche sepolture rituali d'Australia. Nel 2022 i loro resti sono tornati alla comunità aborigena.", cat: "umani", lat: -33.73, lon: 143.05, wiki: "Lago Mungo", wikiEn: "Lake Mungo remains"},
  {t: 0.041, t2: 0.0405, title: "L'escursione di Laschamp", text: "Circa 41.000 anni fa il campo magnetico terrestre si indebolì fino a un decimo e i poli si invertirono per poche centinaia di anni. Più raggi ultravioletti e cosmici raggiunsero il suolo. Alcuni studiosi ipotizzano effetti su ambienti e umani, ma è discusso.", cat: "clima", lat: 45.7, lon: 2.95, wiki: "Evento di Laschamp", wikiEn: "Laschamp event"},
  {t: 0.041, t2: 0.039, title: "Gli ultimi Neanderthal", text: "Tra circa 41.000 e 39.000 anni fa i Neanderthal scompaiono, poco dopo l'arrivo dei sapiens; date più recenti, come a Gibilterra, sono discusse. Le cause furono probabilmente più di una: popolazioni piccole e isolate, clima instabile, concorrenza e assorbimento nei sapiens. Il genoma di «Thorin» (Grotta Mandrin, 2024) mostra gruppi isolati per decine di migliaia di anni.", cat: "umani", lat: 36.12, lon: -5.34, big: true, wiki: "Homo neanderthalensis", wikiEn: "Neanderthal extinction", sci: ["stringer"]},
  {t: 0.0399, title: "L'Ignimbrite campana", text: "Circa 39.900 anni fa i Campi Flegrei, vicino a Napoli, esplosero nella più grande eruzione europea degli ultimi 200.000 anni. La cenere coprì il Mediterraneo orientale fino alla Russia e il clima si raffreddò per alcuni anni. Lo strato di cenere aiuta gli archeologi a datare i siti di sapiens e Neanderthal.", cat: "clima", lat: 40.83, lon: 14.14, wiki: "Ignimbrite campana", wikiEn: "Campanian Ignimbrite eruption"},
  {t: 0.04, title: "Musica e statuette sul Danubio", text: "Nelle grotte del Giura svevo, in Germania, i sapiens di circa 40.000 anni fa intagliavano flauti in osso di avvoltoio e statuette d'avorio, come la Venere di Hohle Fels e l'Uomo-leone. Sono tra le più antiche opere d'arte figurativa d'Europa.", cat: "umani", lat: 48.38, lon: 9.75, wiki: "Venere di Hohle Fels", wikiEn: "Venus of Hohle Fels"},
  {t: 0.04, title: "L'uomo di Tianyuan", text: "In una grotta vicino a Pechino è stato trovato un sapiens di circa 40.000 anni. Il suo DNA, letto dal gruppo di Qiaomei Fu, mostra che appartiene alla linea degli asiatici orientali e dei nativi americani. Mangiava molto pesce d'acqua dolce.", cat: "umani", lat: 39.65, lon: 115.87, wiki: "Uomo di Tianyuan", wikiEn: "Tianyuan man", sci: ["fu"]},
  {t: 0.036, title: "Grotta Chauvet", text: "Nella grotta Chauvet, in Francia, oltre 400 animali dipinti (leoni, rinoceronti, mammut, cavalli) hanno circa 36.000 anni. La tecnica è già raffinata: sfumature, prospettiva, movimento. Fu scoperta nel 1994.", cat: "umani", lat: 44.39, lon: 4.42, wiki: "Grotta Chauvet", wikiEn: "Chauvet Cave"},
  {t: 0.034, title: "Sungir", text: "A Sungir, in Russia, due ragazzi e un uomo furono sepolti circa 34.000 anni fa con migliaia di perline d'avorio di mammut, lance e bracciali. Servirono migliaia di ore di lavoro. I genomi mostrano che i gruppi evitavano di sposarsi tra parenti stretti.", cat: "umani", lat: 56.17, lon: 40.5, wiki: "Sungir", wikiEn: "Sungir", sci: ["willerslev"]},
  {t: 0.032, title: "Cacciatori nell'Artico", text: "Sul fiume Yana, in Siberia, oltre il Circolo Polare Artico, cacciatori di mammut vivevano già circa 32.000 anni fa. Erano gli «antichi Nord-siberiani», una popolazione oggi scomparsa che ha lasciato tracce nei nativi americani.", cat: "umani", lat: 70.73, lon: 135.42, wiki: "Yana RHS", wikiEn: "Yana Rhinoceros Horn Site", sci: ["willerslev"]},
  {t: 0.026, t2: 0.019, title: "L'ultimo massimo glaciale", text: "Tra circa 26.000 e 19.000 anni fa i ghiacci coprono il Canada, la Scandinavia e le Alpi; il mare è 120 metri più basso. Gli umani d'Europa si ritirano in rifugi più caldi (Iberia, Italia, Balcani) e l'Asia e l'America sono unite dalla Beringia. La popolazione del nord si riduce molto.", cat: "clima", lat: 62, lon: 15, big: true, wiki: "Ultimo massimo glaciale", wikiEn: "Last Glacial Maximum"},
  {t: 0.023, title: "Ohalo II: cereali selvatici", text: "Sulle rive del lago di Tiberiade, in Israele, un villaggio di capanne di 23.000 anni conserva semi di orzo e frumento selvatici e una macina. Più di 10.000 anni prima dell'agricoltura, gli umani già raccoglievano e macinavano i cereali.", cat: "umani", lat: 32.72, lon: 35.57, wiki: "Ohalo II", wikiEn: "Ohalo II"},
  {t: 0.023, t2: 0.021, title: "Le impronte di White Sands", text: "Nel New Mexico centinaia di impronte di adulti e bambini, accanto a quelle di mammut e bradipi giganti, sono state datate a 23.000–21.000 anni fa con semi e pollini. Gli umani erano in America già durante il picco glaciale. Alcuni archeologi chiedono ancora conferme, ma le prove si sono rafforzate.", cat: "umani", lat: 32.8, lon: -106.3, wiki: "Impronte di White Sands", wikiEn: "White Sands footprints"},
  {t: 0.02, title: "I primi vasi di ceramica", text: "Nella grotta di Xianrendong, in Cina, frammenti di vasi cotti hanno circa 20.000 anni: sono la ceramica più antica conosciuta. Furono fatti da cacciatori-raccoglitori, non da agricoltori, forse per cucinare e per bevande.", cat: "umani", lat: 28.7, lon: 117.2, wiki: "Grotta di Xianrendong", wikiEn: "Xianrendong Cave"},
  {t: 0.016, title: "Il cane, primo animale domestico", text: "Almeno 15.000 anni fa, forse già 23.000, il lupo diventa cane accanto ai cacciatori dell'ultima glaciazione. A Bonn-Oberkassel un cucciolo malato fu curato e sepolto con due umani. È l'unico animale addomesticato prima dell'agricoltura.", cat: "umani", lat: 50.72, lon: 7.18, wiki: "Canis lupus familiaris", wikiEn: "Domestication of the dog", sci: ["skoglund"]},
  {t: 0.0147, t2: 0.0129, title: "Il caldo improvviso del Bølling-Allerød", text: "Circa 14.700 anni fa le temperature in Europa salgono di diversi gradi in pochi decenni. I ghiacci si ritirano, le foreste avanzano e i cacciatori si spostano verso nord. Nel Levante nasce la cultura natufiana, con i primi villaggi stabili.", cat: "clima", lat: 55, lon: 10, wiki: "Interstadiale Bølling-Allerød", wikiEn: "Bølling–Allerød warming"},
  {t: 0.0145, title: "Monte Verde", text: "In Cile, a Monte Verde, un accampamento di 14.500 anni conserva pali di capanne, alghe, piante medicinali e carne di gonfoteri. Contestato a lungo, oggi è accettato dalla maggior parte degli archeologi. Mostra che gli umani erano arrivati in fondo al Sud America prima della cultura Clovis.", cat: "umani", lat: -41.5, lon: -73.2, wiki: "Monte Verde", wikiEn: "Monte Verde"},
  {t: 0.013, title: "La cultura Clovis", text: "Circa 13.000 anni fa in Nord America si diffondono le punte di lancia Clovis, scheggiate con grande abilità. Per decenni si pensò che i Clovis fossero i primi americani; oggi sappiamo che c'erano umani già prima. Il genoma del bambino di Anzick (Montana) li lega ai nativi americani di oggi.", cat: "umani", lat: 34.28, lon: -103.33, wiki: "Cultura Clovis", wikiEn: "Clovis culture", sci: ["willerslev"]},
  {t: 0.0129, t2: 0.0117, title: "Il Dryas recente", text: "Circa 12.900 anni fa l'emisfero nord torna improvvisamente al freddo per oltre mille anni, forse per un'enorme quantità di acqua dolce dei ghiacciai riversata nell'Atlantico. Nel Levante i Natufiani devono adattarsi: alcuni studiosi pensano che questo li abbia spinti a coltivare.", cat: "clima", lat: 50, lon: -30, wiki: "Dryas recente", wikiEn: "Younger Dryas"},
  {t: 0.0117, title: "Inizia l'Olocene", text: "11.700 anni fa il freddo del Dryas recente finisce in pochi decenni e comincia l'Olocene, il periodo caldo e stabile in cui viviamo. Il mare sale di decine di metri, sommergendo Beringia e Doggerland. Con un clima prevedibile l'agricoltura diventa possibile in molte regioni.", cat: "clima", lat: 72.6, lon: -38.5, big: true, wiki: "Olocene", wikiEn: "Holocene"},
  {t: 0.0116, title: "Göbekli Tepe", text: "In Anatolia sud-orientale, circa 11.600 anni fa, cacciatori-raccoglitori costruiscono recinti di pilastri di pietra alti fino a 5 metri, scolpiti con volpi, serpenti e avvoltoi. È uno dei più antichi monumenti del mondo. Gli scavi recenti mostrano che vi si viveva anche, con case e cisterne.", cat: "umani", lat: 37.22, lon: 38.92, wiki: "Göbekli Tepe", wikiEn: "Göbekli Tepe"},
  {t: 0.0115, t2: 0.0055, title: "Il Sahara verde", text: "Con l'Olocene i monsoni si spostano a nord e il Sahara si riempie di laghi, praterie, ippopotami e coccodrilli. Cacciatori e poi pastori lo popolano e dipingono le rocce del Tassili e dell'Acacus. Circa 5.500 anni fa torna il deserto e le popolazioni si spostano verso il Nilo e il Sahel.", cat: "clima", lat: 22, lon: 13, wiki: "Periodo umido africano", wikiEn: "African humid period"},
  {t: 0.0115, t2: 0.0105, title: "Nasce l'agricoltura nella Mezzaluna fertile", text: "Tra 11.500 e 10.500 anni fa, dall'Anatolia agli Zagros, gli umani cominciano a coltivare farro, monococco, orzo, lenticchie e ceci, e ad allevare capre, pecore, bovini e maiali. Il processo è lento, durato millenni, e avviene in più villaggi contemporaneamente. Il DNA antico mostra che gli agricoltori di Anatolia e di Iran erano popolazioni diverse.", cat: "umani", lat: 36.5, lon: 40, big: true, wiki: "Rivoluzione neolitica", wikiEn: "Neolithic Revolution", sci: ["reich"]},
  {t: 0.011, title: "La Beringia sommersa", text: "Circa 11.000 anni fa il mare in risalita taglia il ponte di terra tra Siberia e Alaska e nasce lo stretto di Bering. I popoli delle Americhe restano separati da quelli dell'Asia fino ai contatti degli ultimi millenni nell'Artico.", cat: "clima", lat: 65.8, lon: -169, wiki: "Beringia", wikiEn: "Beringia"},
  {t: 0.0095, title: "Riso e miglio in Cina", text: "In Cina l'agricoltura nasce in modo indipendente: il riso nel basso Yangtze (Shangshan) e il miglio nella valle del Fiume Giallo, circa 10.000–9.000 anni fa. Si allevano maiali e più tardi bachi da seta. Da qui l'agricoltura si diffonderà in Corea, Giappone e Sud-est asiatico.", cat: "umani", lat: 29.5, lon: 119.9, wiki: "Cultura di Shangshan", wikiEn: "Shangshan culture"},
  {t: 0.0091, t2: 0.008, title: "Çatalhöyük", text: "In Anatolia centrale, circa 9.100 anni fa, sorge un villaggio di migliaia di persone, con case di mattoni attaccate tra loro e senza strade: si entrava dal tetto. Le pareti erano dipinte e i morti sepolti sotto i pavimenti. È uno dei più grandi insediamenti del Neolitico.", cat: "umani", lat: 37.67, lon: 32.83, wiki: "Çatalhöyük", wikiEn: "Çatalhöyük"},
  {t: 0.009, title: "Zucche e mais in Mesoamerica", text: "In Messico gli umani coltivano zucche già 10.000 anni fa e circa 9.000 anni fa, nella valle del Balsas, trasformano il teosinte nel mais. Con fagioli e peperoncini nasce l'agricoltura mesoamericana, che nutrirà Olmechi, Maya e Aztechi.", cat: "umani", lat: 18.3, lon: -99.5, wiki: "Zea mays", wikiEn: "Domestication of maize"},
  {t: 0.0087, t2: 0.006, title: "I primi agricoltori arrivano in Europa", text: "Dall'Anatolia gli agricoltori raggiungono la Grecia circa 8.700 anni fa, l'Italia meridionale circa 8.000 e la Gran Bretagna circa 6.000. Il DNA antico (Wolfgang Haak, David Reich, Johannes Krause) mostra che si spostarono davvero le persone, non solo le idee, mescolandosi poco a poco con i cacciatori-raccoglitori. Molti europei di oggi derivano da questa mescolanza.", cat: "umani", lat: 40.5, lon: 22.5, wiki: "Neolitico europeo", wikiEn: "Neolithic Europe", sci: ["reich", "krause"]},
  {t: 0.0082, title: "L'evento freddo di 8.200 anni fa", text: "Lo svuotamento di enormi laghi glaciali in Nord America raffredda il clima per circa 150 anni. Più o meno nello stesso periodo una grande frana sottomarina al largo della Norvegia (Storegga) provoca uno tsunami, mentre il mare in risalita sommerge le ultime terre di Doggerland, tra Gran Bretagna e Danimarca.", cat: "clima", lat: 54.5, lon: 3, wiki: "Doggerland", wikiEn: "8.2-kiloyear event"},
  {t: 0.008, title: "Patate e quinoa sulle Ande", text: "Sulle Ande, circa 8.000 anni fa, nasce un'altra agricoltura indipendente: patate, quinoa, fagioli, e più tardi lama, alpaca e porcellini d'India. Le coltivazioni a terrazze permettono di vivere oltre 3.500 metri di quota.", cat: "umani", lat: -15.8, lon: -69.4, wiki: "Solanum tuberosum", wikiEn: "History of the potato"},
  {t: 0.0075, title: "Orti in Nuova Guinea", text: "Nella palude di Kuk, sugli altopiani della Nuova Guinea, canali di drenaggio e cumuli di coltivazione mostrano che taro, banane e canna da zucchero erano coltivati circa 7.000 anni fa, con tracce già 10.000 anni fa. È uno dei centri indipendenti dell'agricoltura.", cat: "umani", lat: -5.78, lon: 144.33, wiki: "Kuk Swamp", wikiEn: "Kuk Swamp"},
  {t: 0.007, title: "La prima metallurgia", text: "A Belovode, in Serbia, circa 7.000 anni fa si fondeva il rame dai minerali in forni: è una delle prove più antiche. Poco dopo, nella necropoli di Varna (Bulgaria, circa 6.500 anni fa), compare l'oro lavorato più antico del mondo. Più tardi, mescolando rame e stagno, si otterrà il bronzo.", cat: "umani", lat: 44.3, lon: 21.4, wiki: "Età del rame", wikiEn: "Chalcolithic"},
  {t: 0.0053, title: "Ötzi, l'uomo venuto dal ghiaccio", text: "Circa 5.300 anni fa un uomo muore colpito da una freccia sul ghiacciaio del Similaun, tra Italia e Austria. Il suo corpo mummificato, con abiti, ascia di rame e arco, fu scoperto nel 1991. Il suo genoma è soprattutto di antichi agricoltori anatolici, con la pelle più scura di quanto si pensasse.", cat: "umani", lat: 46.78, lon: 10.84, wiki: "Mummia del Similaun", wikiEn: "Ötzi", sci: ["krause"]},
  {t: 0.0052, title: "Nasce la scrittura", text: "A Uruk, in Mesopotamia, circa 5.200 anni fa, gli scribi tracciano segni su tavolette d'argilla per contare grano e bestiame: nasce la scrittura cuneiforme. Quasi negli stessi anni compaiono i geroglifici egizi. In Cina e in Mesoamerica la scrittura nascerà in modo indipendente più tardi. Comincia la storia scritta.", cat: "umani", lat: 31.32, lon: 45.64, big: true, wiki: "Cuneiforme", wikiEn: "History of writing"},
  {t: 0.005, t2: 0.0045, title: "Dalla steppa: gli Yamnaya", text: "Circa 5.000 anni fa pastori della steppa a nord del Mar Nero, gli Yamnaya, con carri e bestiame, si espandono verso l'Europa e l'Asia centrale. Il DNA antico (Haak, Allentoft, Reich, Willerslev) mostra un grande ricambio di popolazione in Europa centrale e settentrionale. Molti studiosi pensano che abbiano diffuso le lingue indoeuropee; il dibattito continua.", cat: "umani", lat: 47.5, lon: 40, wiki: "Cultura Yamna", wikiEn: "Yamnaya culture", sci: ["reich", "willerslev"]},
  {t: 0.005, t2: 0.0015, title: "L'espansione bantu", text: "Da una regione tra Camerun e Nigeria, circa 5.000 anni fa, agricoltori che parlavano lingue bantu si espandono lentamente verso il Congo, l'Africa orientale e quella australe, raggiunta circa 1.700 anni fa. Portano agricoltura e metallurgia del ferro. Oggi le lingue bantu sono parlate da oltre 350 milioni di persone.", cat: "umani", lat: 5.5, lon: 10.5, wiki: "Espansione bantu", wikiEn: "Bantu expansion"},
  {t: 0.0046, title: "Le piramidi di Giza", text: "Circa 4.600 anni fa il faraone Cheope fa costruire la Grande Piramide, alta 146 metri. Migliaia di lavoratori, nutriti con pane e birra, trasportarono blocchi di pietra lungo canali del Nilo. È la sola delle sette meraviglie del mondo antico ancora in piedi.", cat: "umani", lat: 29.98, lon: 31.13, wiki: "Piramidi di Giza", wikiEn: "Giza pyramid complex"},
  {t: 0.0045, title: "Miglio e sorgo nel Sahel", text: "Con la fine del Sahara verde, i popoli del Sahel domesticano il miglio perla (circa 4.500 anni fa, Mali) e il sorgo (Sudan), e in seguito il riso africano lungo il fiume Niger. L'Africa ha così i suoi centri agricoli indipendenti.", cat: "umani", lat: 15, lon: -1, wiki: "Pennisetum glaucum", wikiEn: "Pearl millet"},
  {t: 0.0042, title: "Il cavallo domestico conquista il mondo", text: "Il DNA di centinaia di cavalli antichi (Librado e colleghi, 2024) mostra che i cavalli domestici di oggi nacquero circa 4.200 anni fa nella steppa tra Volga e Don. In pochi secoli, con il carro da guerra a ruote raggiate, si diffusero dall'Europa alla Cina.", cat: "umani", lat: 48, lon: 42, wiki: "Equus caballus", wikiEn: "Domestication of the horse"},
  {t: 0.0042, title: "La crisi climatica di 4.200 anni fa", text: "Circa 4.200 anni fa una lunga siccità colpisce Mesopotamia, Egitto, valle dell'Indo e Cina. Coincide con la crisi dell'impero accadico e dell'Antico Regno egizio. Gli scienziati discutono su quanto il clima sia stato la causa principale.", cat: "clima", lat: 36.5, lon: 41.5, wiki: "Evento di 4,2 kiloanni", wikiEn: "4.2-kiloyear event"},
  {t: 0.004, title: "Il latte e la lattasi", text: "Gli agricoltori europei consumavano latte già 9.000 anni fa, ma da adulti non lo digerivano. La capacità di digerirlo da grandi (persistenza della lattasi) si diffonde solo negli ultimi 4.000 anni, forse perché aiutava a sopravvivere a carestie ed epidemie (Evershed e colleghi, 2022). È uno degli esempi più chiari di selezione naturale recente negli umani.", cat: "umani", lat: 52, lon: 10, wiki: "Persistenza della lattasi", wikiEn: "Lactase persistence"},
  {t: 0.0033, title: "I navigatori lapita", text: "Circa 3.300 anni fa, nell'arcipelago di Bismarck, compare la ceramica lapita decorata a punzone. In pochi secoli i suoi navigatori raggiungono Vanuatu, Figi, Tonga e Samoa, dove nessun umano era mai arrivato. Discendono da popoli austronesiani partiti da Taiwan.", cat: "umani", lat: -3.5, lon: 151.5, wiki: "Cultura Lapita", wikiEn: "Lapita culture", sci: ["skoglund", "reich"]},
  {t: 0.000688, t2: 0.000675, title: "La peste nera", text: "Il batterio Yersinia pestis della peste nera nacque, secondo il DNA antico (Spyrou, Krause e colleghi, 2022), nella regione del Tian Shan, in Asia centrale, intorno al 1338. Tra il 1347 e il 1351 uccise forse un terzo o metà degli europei. Lasciò tracce anche nei nostri geni del sistema immunitario.", cat: "umani", lat: 42.5, lon: 76, big: true, wiki: "Peste nera", wikiEn: "Black Death", sci: ["krause"]},
  {t: 0.000674, t2: 0.000176, title: "La Piccola età glaciale", text: "Tra il 1300 e il 1850 circa l'emisfero nord si raffredda leggermente: i ghiacciai alpini avanzano, il Tamigi gela, i raccolti falliscono più spesso. Le colonie norrene della Groenlandia vengono abbandonate verso il 1450. Le cause furono eruzioni vulcaniche e un Sole un po' meno attivo.", cat: "clima", lat: 46.5, lon: 8, wiki: "Piccola era glaciale", wikiEn: "Little Ice Age"},
  {t: 0.000534, title: "Lo scambio colombiano", text: "Dal 1492, con i viaggi di Colombo, piante, animali e malattie attraversano l'Atlantico. Mais, patate e pomodori arrivano in Europa, cavalli, grano e bovini nelle Americhe. Vaiolo e morbillo uccidono la grande maggioranza dei nativi americani; milioni di africani vengono deportati come schiavi. Il mondo si mescola come mai prima.", cat: "umani", lat: 24.1, lon: -74.5, big: true, wiki: "Scambio colombiano", wikiEn: "Columbian exchange"},
  {t: 0.000266, title: "La rivoluzione industriale", text: "Dalla metà del Settecento, in Inghilterra, macchine a vapore alimentate a carbone cambiano il lavoro, i trasporti e le città. La popolazione mondiale supera il miliardo intorno al 1804 e comincia a crescere sempre più in fretta. Comincia anche l'aumento dell'anidride carbonica nell'atmosfera.", cat: "umani", lat: 53.48, lon: -2.24, big: true, wiki: "Rivoluzione industriale", wikiEn: "Industrial Revolution"},
  {t: 0.000016, title: "Il genoma dei Neanderthal", text: "Nel 2010 il gruppo di Svante Pääbo, a Lipsia, pubblica la prima bozza del genoma neanderthaliano e, nello stesso anno, scopre i Denisova dal DNA di un dito. Nasce la paleogenomica, che ha riscritto la storia umana. Pääbo riceverà il premio Nobel nel 2022.", cat: "umani", lat: 51.32, lon: 12.39, wiki: "Svante Pääbo", wikiEn: "Neanderthal genome project", sci: ["paabo"]},
  {t: 0.000004, title: "Otto miliardi di persone", text: "Il 15 novembre 2022, secondo l'ONU, la popolazione mondiale ha raggiunto 8 miliardi; nel 2026 è circa 8,3 miliardi. La crescita sta rallentando: le Nazioni Unite prevedono un massimo di circa 10,3 miliardi verso il 2080. Ci sono voluti 200.000 anni per arrivare al primo miliardo e solo 12 anni per passare da 7 a 8.", cat: "umani", lat: 20, lon: 78, big: true, wiki: "Popolazione mondiale", wikiEn: "World population"}
);

